/**
 * Display-block authoring types — the typed shapes an author places in
 * `app({ displayBlocks: {...} })` (record-view layout) and
 * `app({ recordCreateDisplayBlocks: {...} })` (new-record form).
 *
 * A display block controls how a record's fields and components are
 * laid out in the UI. Each bag is keyed by an author-chosen handle;
 * each entry is a discriminated variant keyed on `kind`. The platform
 * stores all variant data inside one JSON `properties` column plus a
 * few flat columns (`fieldId`, `stageId`, parent linkage); the
 * serializer translates these typed shapes into that wire form, and
 * the deserializer inverts it.
 *
 * Two structural rules mirror the platform:
 *   - **Children-on-parent.** A `group` block lists its child blocks
 *     by bag key in `blocks: ["title", "status"]`. Children stay at
 *     the top level of the bag (no `parent` slot); the serializer
 *     wires the parent linkage from the group's `blocks` list.
 *   - **Stage scoping is top-level only.** `stage` is honored on
 *     top-level bag entries; a group's children inherit the group's
 *     stage. Omit `stage` for the default (unstaged) layout.
 */
/**
 * The `kind` discriminator → platform `DisplayBlockType` enum value.
 * The serializer stamps the enum into each block's `properties.type`.
 */
export const DISPLAY_BLOCK_KIND_TO_TYPE = {
    group: "GROUP",
    field: "FIELD",
    widget: "WIDGET",
    comments: "COMMENTS",
    attachment: "ATTACHMENTS",
    activityLog: "ACTIVITY_LOG",
    status: "STATUS",
    relatedItems: "RELATED_ITEMS",
    relatedTasks: "RELATED_TASKS",
    approvals: "APPROVALS",
    surveys: "SURVEYS",
    relatedCreate: "RELATED_CREATE",
};
/**
 * Read-side GraphQL `__typename` → `kind`. The pull response
 * discriminates blocks by their concrete GraphQL type name
 * (`AspectCommentsDisplayBlock`, …), NOT by the `DisplayBlockType`
 * enum the write side stamps into `properties.type` — so the
 * deserializer keys off this map, not {@link DISPLAY_BLOCK_KIND_TO_TYPE}.
 */
export const DISPLAY_BLOCK_TYPENAME_TO_KIND = {
    AspectGroupDisplayBlock: "group",
    AspectFieldDisplayBlock: "field",
    AspectWidgetDisplayBlock: "widget",
    AspectCommentsDisplayBlock: "comments",
    AspectAttachmentDisplayBlock: "attachment",
    AspectActivityLogDisplayBlock: "activityLog",
    AspectStatusDisplayBlock: "status",
    AspectRelatedItemsDisplayBlock: "relatedItems",
    AspectRelatedTasksDisplayBlock: "relatedTasks",
    AspectApprovalsDisplayBlock: "approvals",
    AspectSurveysDisplayBlock: "surveys",
    AspectRelatedCreateDisplayBlock: "relatedCreate",
};
